import os
import torch


class Config:
    """
    Configuration for the Massive-Capacity Stabilized Decoupled BiGRU (MC-SD-BiGRU) strategy.
    """

    # ==========================================
    # System Settings
    # ==========================================
    SEED = 42
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    NUM_WORKERS = 2  # Number of dataloader workers

    # ==========================================
    # File Paths & Directories
    # ==========================================
    # Metadata generated by the metadata script
    METADATA_DIR = "./metadata"
    TRAIN_DATA_PATH = os.path.join(METADATA_DIR, "train.parquet")
    VAL_DATA_PATH = os.path.join(METADATA_DIR, "val.parquet")
    TEST_DATA_PATH = os.path.join(METADATA_DIR, "test.parquet")

    # Working directory for this specific idea/run
    WORKING_DIR = "./working/idea_84"
    CACHE_DIR = WORKING_DIR

    # Output paths
    MODEL_SAVE_PATH = os.path.join(WORKING_DIR, "best_model.pth")
    SUBMISSION_PATH = os.path.join(WORKING_DIR, "submission.csv")

    # Ensure working directory exists
    os.makedirs(WORKING_DIR, exist_ok=True)

    # ==========================================
    # Data Specifications
    # ==========================================
    SEQ_LEN = 107
    SEQ_SCORED = 68

    # Input Features:
    # One-hot Sequence (4) + One-hot Structure (3) + One-hot LoopType (7) = 14
    INPUT_DIM = 14

    # Targets
    NUM_TARGETS = 5
    TARGET_COLS = ["reactivity", "deg_Mg_pH10", "deg_pH10", "deg_Mg_50C", "deg_50C"]
    SCORED_TARGET_COLS = ["reactivity", "deg_Mg_pH10", "deg_Mg_50C"]

    # ==========================================
    # Model Architecture (Massive-Capacity)
    # ==========================================
    # Convolutional Stem
    CNN_KERNEL_SIZE = 3
    CNN_FILTERS = 512  # Matches hidden dim for projection

    # Recurrent Backbone
    HIDDEN_DIM = 512  # Hidden dimension per direction (Total = 1024)
    NUM_LAYERS = 4  # Deep backbone

    # Regularization & Stability
    DROPOUT = 0.1

    # ==========================================
    # Training Hyperparameters
    # ==========================================
    BATCH_SIZE = 16  # Moderate batch size for large model
    EPOCHS = 50  # Max epochs
    LEARNING_RATE = 1e-3
    WEIGHT_DECAY = 1e-4

    # Stability Mechanisms
    GRAD_CLIP = 1.0  # Mandatory gradient clipping

    # Early Stopping
    PATIENCE = 10
